const { chromium } = require('playwright');
const fs = require('fs');

(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage();
  const htmlContent = fs.readFileSync('index.html', 'utf-8');

  await page.setContent(htmlContent, { waitUntil: 'load' });

  const axePath = require.resolve('axe-core');
  const axeSource = fs.readFileSync(axePath, 'utf-8');
  await page.evaluate((source) => {
    eval(source);
  }, axeSource);

  const results = await page.evaluate(async () => {
    return await window.axe.run();
  });

  await browser.close();

  const wcag = results.violations.filter(v => !v.tags.includes('best-practice'));
  const bp = results.violations.filter(v => v.tags.includes('best-practice'));

  console.log('=== WCAG VIOLATIONS ===');
  wcag.forEach(v => {
    console.log('ID:', v.id, '| Impact:', v.impact);
    console.log('Description:', v.description);
    console.log('Targets:', v.nodes.map(n => n.target).join(', '));
    console.log('---');
  });

  console.log('\\n=== BEST PRACTICE VIOLATIONS ===');
  bp.forEach(v => {
    console.log('ID:', v.id);
    console.log('Description:', v.description);
    console.log('Targets:', v.nodes.map(n => n.target).join(', '));
    console.log('---');
  });

  console.log('\\nPasses:', results.passes.length);
  console.log('WCAG Violations:', wcag.length);
  console.log('Best Practice Violations:', bp.length);

  process.exit(wcag.length > 0 ? 1 : 0);
})();
